// Service worker of the NeoPHP Notifier package: displays the push notifications and opens their page on click.
// Generated by php bin/neo notifier:service-worker; register it with navigator.serviceWorker.register('/notifier-sw.js').
self.addEventListener('push', (event) => {
    let notification = {};

    try {
        notification = event.data ? event.data.json() : {};
    } catch (error) {
        notification = { subject: event.data ? event.data.text() : '' };
    }

    const data = notification.data || {};

    event.waitUntil(self.registration.showNotification(notification.subject || 'Notification', {
        body: notification.content || '',
        icon: data.icon || undefined,
        badge: data.badge || undefined,
        image: data.image || undefined,
        tag: data.tag || undefined,
        renotify: Boolean(data.tag),
        requireInteraction: notification.importance === 'urgent',
        data: { url: notification.url || '/' },
    }));
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    const url = new URL((event.notification.data && event.notification.data.url) || '/', self.location.origin).href;

    event.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windows) => {
        for (const client of windows) {
            if (client.url === url && 'focus' in client) {
                return client.focus();
            }
        }

        return self.clients.openWindow(url);
    }));
});